function generate(rand, size) {
  const target = size === 'large' ? 50 : 1 + Math.floor(rand() * 8);
  const top = size === 'large' ? 50 : 1 + Math.floor(rand() * 10);
  const twiceChance = rand();
  const values = Array.from({ length: top }, (_, i) => i + 1);
  for (let i = values.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [values[i], values[j]] = [values[j], values[i]];
  }
  const nums = [];
  for (const value of values) {
    if (nums.length >= target) break;
    nums.push(value);
    if (nums.length < target && rand() < twiceChance) nums.push(value);
  }
  for (let i = nums.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [nums[i], nums[j]] = [nums[j], nums[i]];
  }
  return [nums];
}
